#include "safety.h"
#include "../config.mcc/mcc_generated_files/system/pins.h"
#include "registers.h"

volatile bool EngineCanRun = false;
volatile bool BladesCanRun = false;
volatile bool DO_EN_IS_ON = false;

bool Safety_EngineCanRun () {
  return EngineCanRun;
}

bool Safety_BladeCanRun() {
  return BladesCanRun;
}

bool Safety_SeatIsOccupied() {
  return (global_shadow_ram[REG_IN_B1] & 0x01) > 0;
}

bool Safety_BrakeActivated() {
  return (global_shadow_ram[REG_IN_B1] & 0x02) > 0;
}

bool Safety_ContactActivated() {
  return (global_shadow_ram[REG_IN_B1] & 0x04) > 0;
}

bool Safety_StartActivated() {
  return (global_shadow_ram[REG_IN_B2] & 0x02) > 0;
}


void SafetySrLoop(void) {
  DO_EN_IS_ON = false;
  // The safety loop is split into two parts:
  // - the interrupt service routine (SR), called first by the RTC interrupt;
  // and
  // - the main-loop routine, which handles the non-immediate safety logic.
  //
  // The SR does not read the SPI bus or authorize any action. It only checks
  // the last known safety state and decides whether DO_EN must be cut. When
  // cut, DO_EN immediately disables all output MOSFETs, and therefore the
  // output relays.

  // The engine can run if:
  // - the MC33978AES state was successfully read during the previous cycle; and
  // - the seat is occupied or the brake is engaged.
  EngineCanRun = false;
  bool brakeActivated = Safety_BrakeActivated();
  bool seatIsOccupied = Safety_SeatIsOccupied();
  if (_SWITCH_STATUS_DONE && (brakeActivated || seatIsOccupied)) {
    EngineCanRun = true;
  }

  // The blades can run if:
  // - the MC33978AES state was successfully read during the previous cycle; and
  // - the engine is running; and
  // - the seat is occupied.

  // In the SR, we only perform the immediate safety cut-off. The main loop
  // is responsible for deciding whether specific actions may be authorized,
  // including any required delays or additional checks.

  if (!EngineCanRun) {
    IO_DO_EN_SetLow();
    DO_EN_IS_ON = false;
  }

  _SWITCH_STATUS_DONE = false;
}

void SafetyMainLoop(void) {
  if (EngineCanRun) {
    // TODO : temporiser de 1seconde
    DO_EN_IS_ON = true;
    IO_DO_EN_SetHigh();
  }
}
